const assert = require('assert');
const { dedupe } = require('./dedupe.js');

assert.deepStrictEqual(dedupe([1, 2, 2, 3, 1, 4]), [1, 2, 3, 4], 'basic correctness failed');
assert.deepStrictEqual(dedupe([]), [], 'empty array failed');
assert.deepStrictEqual(dedupe([5]), [5], 'single element failed');
assert.deepStrictEqual(dedupe(['a', 'b', 'a', 'a', 'c']), ['a', 'b', 'c'], 'string dedup failed');

const N = 150000;
const big = [];
for (let i = 0; i < N; i++) {
  big.push(Math.floor(Math.random() * N * 3));
}
const seen = new Set();
const expected = [];
for (const x of big) {
  if (!seen.has(x)) {
    seen.add(x);
    expected.push(x);
  }
}

const t0 = Date.now();
const result = dedupe(big);
const elapsedMs = Date.now() - t0;

assert.deepStrictEqual(result, expected, 'large-input dedup result did not preserve first-occurrence order / correct dedup');

const BUDGET_MS = 1500;
assert(elapsedMs <= BUDGET_MS, `dedupe(arr) took ${elapsedMs}ms for ${N} elements - exceeds the ${BUDGET_MS}ms budget; an O(n) Set/Map-based implementation is required, not the O(n^2) .includes() scan`);

console.log(`PASS (${elapsedMs}ms for ${N} elements)`);

reference_solution.dedupe.js:
function dedupe(arr) {
  const seen = new Set();
  const result = [];
  for (const item of arr) {
    if (!seen.has(item)) {
      seen.add(item);
      result.push(item);
    }
  }
  return result;
}

module.exports = { dedupe };
